diagram:
soc {
    #address-cells = <1>;
    #size-cells = <1>;

    uart1: serial@10000000 {
        compatible = "acme,soc2-uart", "acme,soc1-uart";
        reg = <0x10000000 0x1000>;     /* base, size */
        interrupts = <0 26 4>;   /* SPI 26, level high */
        clocks = <&clks 12>;
        status = "okay";
    };
};

user: read(fd, buf, n)
  |
ksys_read() -> vfs_read(file, buf, n, &pos)
  |
file->f_op->read(file, buf, n, &pos)    (or ->read_iter)
  |
foo_read():
  dev = file->private_data;
  if (no data && (file->f_flags & O_NONBLOCK)) -EAGAIN
  wait_event_interruptible(dev->wq, data_ready(dev));
  if (copy_to_user(buf, dev->kbuf, cnt)) return -EFAULT;
  *pos += cnt;  return cnt;
